viewStyle.result:
#app{
  --ada-unit:1;
  --ada-notice-reserve:calc(var(--ada-unit) * 50.75px);
  --ada-hud-top:calc(var(--ada-unit) * 8px);
  --ada-hud-right:calc(var(--ada-unit) * 8px);
  --ada-hud-left:calc(var(--ada-unit) * 8px);
  --ada-safe-top:0px;
  --ada-safe-right:0px;
  --ada-safe-bottom:0px;
  --ada-safe-left:0px;
  --ada-slice-2:2px;
  --ada-slice-4:4px;
  --ada-slice-6:6px;
}

.ada-safe-probe{
  position:absolute;
  top:0;
  left:0;
  width:0;
  height:0;
  visibility:hidden;
  pointer-events:none;
  padding:var(--inset-top,0px) var(--inset-right,0px) var(--inset-bottom,0px) var(--inset-left,0px)
}
